package com.sportradar.worldcup.scoreboard;

/**
 * Immutable snapshot of a match at the moment it was read.
 *
 * @param id         identifier generated by the library when the match was started
 * @param team1      first (home) team name, trimmed
 * @param team2      second (away) team name, trimmed
 * @param team1Score goals of {@code team1}, never negative
 * @param team2Score goals of {@code team2}, never negative
 */
public record MatchSummary(MatchId id,
                           String team1,
                           String team2,
                           int team1Score,
                           int team2Score) {}
